const {test}=require('node:test');
const assert=require('node:assert/strict');
const E=require('../dist/engine.js');
const ticks=(s,n)=>{for(let i=0;i<n;i++)E.tick(s);};
function rich(){let s=E.fresh();for(let k in s.cities[0].stock)s.cities[0].stock[k]=100;return s;}
test('Placement charges once and rejects water, occupied tiles and missing resources',()=>{let c=E.fresh().cities[0];assert.equal(E.place(c,'wood',7,9),'');assert.equal(c.stock.wood,39);assert.ok(E.place(c,'wood',7,9));assert.equal(c.stock.wood,39);assert.ok(E.place(c,'house',0,0));assert.ok(E.place(c,'salt',7,8));});
test('Production requires a connected road and consumes exact inputs',()=>{let s=E.fresh(),c=s.cities[0];E.place(c,'saw',7,8);let initial=c.stock.wood;ticks(s,10);assert.equal(c.stock.wood,initial);assert.equal(E.place(c,'road',6,8),'');ticks(s,10);assert.equal(c.stock.wood,initial-2);assert.equal(c.stock.plank,24);});
test('Full output storage blocks consumption',()=>{let s=rich(),c=s.cities[0];E.place(c,'saw',7,9);c.stock.plank=120;let n=c.stock.wood;ticks(s,10);assert.equal(c.stock.wood,n);assert.equal(c.stock.plank,120);});
test('Food shortage recovers after supply resumes',()=>{let s=E.fresh(),c=s.cities[0];c.stock.fish=0;c.stock.grain=0;ticks(s,20);assert.equal(c.hunger,1);c.stock.fish=6;ticks(s,20);assert.equal(c.hunger,0);assert.equal(c.stock.fish,3);});
test('Farm changes to horse feed',()=>{let s=E.fresh(),c=s.cities[0];E.place(c,'farm',7,9);c.buildings.at(-1).mode='feed';ticks(s,12);assert.equal(c.stock.feed,15);assert.equal(c.stock.grain,8);});
test('Sea transport reserves goods, delivers and returns',()=>{let s=rich();E.found(s,1);let a=s.cities[0],b=s.cities[1];b.stock.salt=20;assert.equal(E.route(s,0,1,'sea','wood','salt',6,4),'');let w=a.stock.wood;ticks(s,1);assert.equal(a.stock.wood,w-6);assert.equal(s.routes[0].cargo,6);let bw=b.stock.wood;ticks(s,24);assert.equal(b.stock.wood,bw+6);ticks(s,25);assert.equal(a.stock.salt,106);assert.equal(s.deliveries,12);});
test('Full destination retains cargo until space exists',()=>{let s=rich();E.found(s,1);E.route(s,0,1,'sea','wood','salt');s.cities[1].stock.wood=120;ticks(s,25);assert.equal(s.routes[0].cargo,6);assert.equal(s.deliveries,0);s.cities[1].stock.wood=115;ticks(s,1);assert.equal(s.routes[0].cargo,1);assert.equal(s.deliveries,5);s.cities[1].stock.wood=119;ticks(s,1);assert.equal(s.routes[0].cargo,0);assert.equal(s.routes[0].direction,1);});
test('Land route carrying feed never uses the same feed twice',()=>{let s=rich();E.found(s,1);E.found(s,2);assert.equal(E.route(s,0,2,'land','feed','clay',12,0),'');s.cities[0].stock.feed=5;ticks(s,1);assert.equal(s.cities[0].stock.feed,0);assert.equal(s.routes[0].cargo,4);});
test('Land route waits without feed and enforces land connectivity',()=>{let s=rich();E.found(s,1);E.found(s,2);assert.ok(E.route(s,0,1,'land','wood','salt'));assert.equal(E.route(s,0,2,'land','wood','clay'),'');s.cities[0].stock.feed=0;ticks(s,1);assert.equal(s.routes[0].cargo,0);assert.match(s.routes[0].blocked,/Futter/);});
test('Invalid reserve rejected without charging',()=>{let s=rich();E.found(s,1);let w=s.cities[0].stock.wood;for(let reserve of [NaN,Infinity,-1,1.5,101])assert.ok(E.route(s,0,1,'sea','wood','salt',6,reserve));assert.equal(s.cities[0].stock.wood,w);});
test('Pause preserves complete simulation and save roundtrip',()=>{let s=E.fresh();s.paused=true;let before=JSON.stringify(s);ticks(s,100);assert.equal(JSON.stringify(s),before);assert.deepEqual(E.parseSave(before),s);assert.throws(()=>E.parseSave('{"version":2}'));});
test('Playable opening reaches bread, village and a second town with starting resources',()=>{let s=E.fresh(),c=s.cities[0];let build=(t,x,y)=>assert.equal(E.place(c,t,x,y),'',t);build('wood',7,9);build('saw',7,10);ticks(s,80);build('road',6,8);build('road',6,7);build('road',6,6);build('road',6,5);build('house',5,8);build('house',5,7);build('farm',7,8);build('mill',7,7);build('bakery',7,6);build('farm',7,5);let reached=false;for(let i=0;i<1500;i++){E.tick(s);if(!E.upgrade(c)){reached=true;break;}}assert.ok(reached,'village should be attainable');ticks(s,150);assert.equal(E.found(s,1),'');assert.equal(s.cities.length,2);assert.equal(c.level,1);});
